insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_dance1_v1'
from (values
('117.205.c.1.A',1,'A sixth grader moves around the room without bumping into classmates. She is showing good:','["spatial awareness", "tuning skill", "reading speed", "paint control"]'::jsonb,0,'Spatial awareness means knowing where your body is in relation to others and the room.','original'),
('117.205.c.1.A',2,'Feeling the sensation of your own arm rising overhead with your eyes closed is part of:','["visual art", "kinesthetic awareness", "costume design", "lighting design"]'::jsonb,1,'Kinesthetic awareness is sensing body movement and position.','original'),
('117.205.c.1.B',1,'Which habit supports a healthy lifestyle for a dancer?','["avoiding all exercise", "skipping meals before class", "drinking water and getting enough sleep", "staying up all night"]'::jsonb,2,'Wellness includes nutrition, hydration and rest.','original'),
('117.205.c.1.B',2,'Wellness for dancers includes caring for the body and the:','["costumes only", "audience seats", "stage curtains", "mind and emotions"]'::jsonb,3,'Wellness covers physical, mental and emotional health.','original'),
('117.205.c.1.C',2,'The vocabulary term ''plié'' in ballet means to:','["bend the knees", "turn quickly", "kneel on the floor", "jump high"]'::jsonb,0,'A plié is a bending of the knees.','original'),
('117.205.c.1.C',2,'Learning how muscles and bones work together to move is part of:','["lighting", "body science", "set painting", "costume sewing"]'::jsonb,1,'Body science explains anatomy for dance.','original'),
('117.205.c.1.D',2,'The dance element of space includes direction, level, and:','["volume", "rhyme", "pathway", "tuning"]'::jsonb,2,'Space includes direction, level, size and pathway.','original'),
('117.205.c.1.D',2,'Fast, slow, and steady beats are part of the dance element of:','["energy only", "space only", "costume", "time"]'::jsonb,3,'Time includes tempo, rhythm and duration.','original'),
('117.205.c.2.A',1,'Good alignment when standing in dance means:','["keeping the head over the shoulders, hips and feet", "hunching the back", "locking the knees back", "leaning forward as far as possible"]'::jsonb,0,'Proper alignment stacks the body parts in a line.','original'),
('117.205.c.2.A',2,'Why do dancers practice proper alignment?','["to use less space", "to move safely and prevent injury", "to avoid music", "to look taller only"]'::jsonb,1,'Alignment protects the body and improves movement.','original'),
('117.205.c.2.B',2,'Making up movement on the spot without planning is called:','["costuming", "notation", "improvisation", "rehearsal"]'::jsonb,2,'Improvisation is spontaneous movement.','original'),
('117.205.c.2.B',3,'Using choreographic forms like AB or ABA, a dance with the pattern ABA:','["has no repeat", "uses three different sections", "only has one movement", "returns to the first phrase at the end"]'::jsonb,3,'ABA returns to the opening section.','original'),
('117.205.c.2.C',2,'Reaching forward, sideways and backward in a movement study uses spatial:','["directions", "notes", "volumes", "colors"]'::jsonb,0,'Directions are a part of space.','original'),
('117.205.c.2.C',2,'A movement study that follows a steady count of four uses:','["cooking skills", "rhythmical skills", "math drills only", "painting skills"]'::jsonb,1,'Counting beats builds rhythm.','original'),
('117.205.c.2.D',2,'A dancer shows joy by using big, bouncy movements. This is an expression of:','["a price list", "a weather map", "an emotion", "a bus route"]'::jsonb,2,'Dance can express emotions and ideas.','original'),
('117.205.c.2.D',2,'In a group dance about a storm, the dancers rush and swirl together to express:','["a recipe", "a grade", "a math fact", "an idea"]'::jsonb,3,'Dance can express ideas as well as feelings.','original'),
('117.205.c.3.A',1,'Which dance style is known for shoes with metal plates that make rhythmic sounds?','["tap", "modern", "folk", "ballet"]'::jsonb,0,'Tap uses metal plates on shoes.','original'),
('117.205.c.3.A',2,'A dance style that grew out of expressive freedom and floor work, breaking from classical ballet rules, is:','["flamenco only", "modern dance", "square dance", "tap"]'::jsonb,1,'Modern dance emphasizes expression and freedom.','original'),
('117.205.c.3.B',2,'When performing for an audience, dancers should:','["look at the floor the whole time", "ignore the music", "project energy and focus to communicate the dance", "leave early"]'::jsonb,2,'Performers communicate intent to viewers.','original'),
('117.205.c.3.B',2,'A group performance works best when dancers:','["move at random", "avoid rehearsal", "talk through the piece", "stay in unison or in planned relationship"]'::jsonb,3,'Groups rehearse to coordinate.','original'),
('117.205.c.3.C',3,'A choreographer uses a video recording of rehearsal to:','["review spacing and timing", "buy tickets", "mix paint", "paint a set"]'::jsonb,0,'Technology can help evaluate dance practice.','original'),
('117.205.c.3.C',3,'Which technology might a dance team use in performance?','["a typewriter", "stage lighting cues and recorded music", "a pencil sharpener", "a sewing needle"]'::jsonb,1,'Technology supports performances.','original'),
('117.205.c.3.D',1,'A warm-up before dancing helps:','["skip practice", "tire the body", "prepare muscles and prevent injury", "avoid the music"]'::jsonb,2,'Warm-ups raise body temperature and ready the muscles.','original'),
('117.205.c.3.D',2,'The cool-down at the end of class should include:','["sprints", "heavy lifting", "jumps", "slow movement and stretching"]'::jsonb,3,'Cool-downs lower heart rate gradually.','original'),
('117.205.c.4.A',3,'A dance performed at a harvest festival has cultural significance because it:','["reflects a community''s traditions and history", "uses no music", "is always fast", "has no meaning"]'::jsonb,0,'Dances communicate culture and history.','original'),
('117.205.c.4.A',3,'Learning when and where a dance began helps students understand its:','["price", "historical context", "weight", "color"]'::jsonb,1,'History explains why a dance developed.','original'),
('117.205.c.4.B',3,'A movement characteristic of a historical folk dance might be:','["texting", "typing", "skipping steps in a circle formation", "driving"]'::jsonb,2,'Folk dances have recognizable patterns.','original'),
('117.205.c.4.B',3,'Dancers who shaped historical dance forms are called:','["spectators", "judges only", "ticket sellers", "contributing choreographers and performers"]'::jsonb,3,'Identify the people who contributed to a form.','original'),
('117.205.c.4.C',2,'A dance that represents your own family''s culture shows your:','["heritage", "homework", "schedule", "locker"]'::jsonb,0,'Heritage dances come from a person''s background.','original'),
('117.205.c.4.C',2,'A dance that tells about the place where you live represents your:','["calendar", "environment", "pencil", "clock"]'::jsonb,1,'Place-based dances reflect environment.','original'),
('117.205.c.4.D',2,'A music video that features choreography shows dance in:','["a closet", "a library card", "media", "a textbook only"]'::jsonb,2,'Dance appears in film, TV and online media.','original'),
('117.205.c.4.D',3,'Dancing out a story from a social studies lesson connects dance to:','["a doorbell", "a paperclip", "a coupon", "another content area"]'::jsonb,3,'Dance can illustrate lessons in other subjects.','original'),
('117.205.c.5.A',3,'Evaluating a performance for quality uses:','["dance vocabulary and clear criteria", "guesses", "only the ticket price", "gossip"]'::jsonb,0,'Evaluation uses terms and criteria.','original'),
('117.205.c.5.A',3,'Which comment is most helpful feedback after a performance?','["I was bored.", "The group''s timing stayed together during the quick section.", "Some people clapped.", "It was fine."]'::jsonb,1,'Specific observations make feedback useful.','original'),
('117.205.c.5.B',3,'Studying the patterns in a dance to see equal groups connects dance to:','["plumbing", "boating", "mathematics", "spelling"]'::jsonb,2,'Counting and patterns link dance and math.','original'),
('117.205.c.5.B',2,'The way sound travels and music is made links dance to:','["cooking only", "parking", "mail", "music and science"]'::jsonb,3,'Dance relates to music and science.','original'),
('117.205.c.5.C',3,'An American choreographer is a person who:','["creates dances using the American dance tradition", "sells costumes", "paints scenery", "makes tickets"]'::jsonb,0,'American choreographers design dances in American styles.','original'),
('117.205.c.5.C',3,'A choreographic structure is the:','["price of the show", "way a dance is organized in sections", "color of the stage", "number of seats"]'::jsonb,1,'Structure organizes movement.','original'),
('117.205.c.5.D',3,'A student explains why she used slow, low movements in her solo to show sadness. She is describing her:','["bus ride", "lunch order", "artistic decisions", "phone plan"]'::jsonb,2,'Artistic decisions are the choices behind a work.','original'),
('117.205.c.5.D',3,'Changing a dance''s ending after feedback is an example of making a:','["bill", "mistake", "excuse", "revision to improve the work"]'::jsonb,3,'Revision reflects artistic decision-making.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
